import {
  MeshBasicNodeMaterial,
  Mesh,
  PlaneGeometry,
  Group,
  TextureLoader,
  Cache,
  Color
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Background image plane ---
  const atlasRegion = config.atlasRegion || { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlasRegion.width / atlasRegion.height;
  const planeWidth = 2.4; // arbitrary but keeps scale 1
  const planeHeight = planeWidth / aspect;

  const bgGeo = new PlaneGeometry(planeWidth, planeHeight);
  const bgMat = new MeshBasicNodeMaterial({
    map: ctx.textureLoader ? ctx.textureLoader.load(config.imageUrl) : null,
    transparent: true,
    side: 0 // default front
  });
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -0.01); // slightly behind text
  group.add(bgMesh);

  // --- Text via font atlas ---
  let textMesh = null;
  if (config.textContent && ctx.fontAtlas) {
    const textConfig = {
      text: config.textContent, // "Atelier Noir — precise · luxury · technical"
      fontFamily: 'Lora', // from typography display
      fontWeight: 400,
      fontSize: 0.34, // scene units – headline size from design tokens
      color: new Color(config.colors?.paper || '#e8ecf2'),
      align: 'center',
      // offset to center on plane
      position: { x: 0, y: 0, z: 0.01 }
    };
    // Assuming ctx.fontAtlas.createText returns an Object3D
    textMesh = ctx.fontAtlas.createText(textConfig);
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  }

  // --- Scene placement ---
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x || 0,
      config.scenePosition.y || 1.85,
      config.scenePosition.z || 0
    );
  }
  if (config.sceneRotation) {
    group.rotation.set(
      config.sceneRotation.x || 0,
      config.sceneRotation.y || 0,
      config.sceneRotation.z || 0
    );
  }
  if (config.sceneScale) {
    group.scale.set(
      config.sceneScale.x || 1,
      config.sceneScale.y || 1,
      config.sceneScale.z || 1
    );
  }

  // --- No handlers or data bindings ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    bgGeo.dispose();
    bgMat.dispose();
    if (bgMat.map) bgMat.map.dispose();
    if (textMesh && textMesh.userData.cleanup) {
      textMesh.userData.cleanup();
    }
    // Kill any GSAP tweens on this object
    gsap.killTweensOf(group);
  };

  return group;
}
